import base64
import os

files = {
    'frontend/src/pages/AdminDashboardPage.tsx': b'''
''',
    
    'frontend/src/components/ChatWidget.tsx': b'''
''',
    
    'frontend/src/components/BookingSlideOver.tsx': b'''
'''
}

for filepath, content_b64 in files.items():
    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(base64.b64decode(content_b64).decode('utf-8'))
        
print("Wrote files perfectly with utf-8!")
